mapper.update:
UPDATE user
USER_NAME=#{userName}, USER_TEL=#{userTel}, USER_EMAIL=#{userEmail}, USER_NICK=#{userNick}, PASSWORD=#{password}, SALT=#{salt}, CREATE_TIME=#{createTime}, IS_DELETE=#{isDelete}
USER_ID=#{userId}

mapper.select:
SELECT * FROM user

        USER_NAME LIKE CONCAT('%',#{userName},'%')
        AND USER_TEL=#{userTel}
        AND USER_EMAIL=#{userEmail}
        AND USER_NICK=#{userNick}
        AND IS_DELETE=#{isDelete}
        AND USER_ID=#{userId}
        AND CREATE_TIME >= #{startTime} AND CREATE_TIME <= #{endTime}
